INSERT INTO itineraries(trip_id,location_id,day_number,start_time,end_time,note) SELECT t.id,l.id,1,'08:00','11:00','Điểm tham quan gợi ý cho hành trình.' FROM trips t JOIN locations l ON l.name='Phố cổ Hà Nội' AND l.destination='Hà Nội' WHERE t.name='Khám phá Hà Nội 3N2Đ' AND t.owner_id=1 AND NOT EXISTS (SELECT 1 FROM itineraries i WHERE i.trip_id=t.id AND i.day_number=1);
